package kz.qorgan.core.model

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonObject

/**
 * The parts of `site/core/qorgan-config.json` the text core needs. Parsed from the very file the
 * web client loads (generated by `python -m qorgan.web.client_config`), never re-typed here.
 */
data class QorganConfig(
    val locales: List<String>,
    val defaultLocale: String,
    val window: WindowConfig,
    val meter: MeterConfig,
    val scoring: ScoringConfig,
    val hardSignalIds: List<String>,
    val tactics: Map<String, Map<String, String>>, // tactic id -> locale -> display name
    val advice: Map<String, AdviceTexts>,
    val templates: Map<String, Templates>,
    val embedder: EmbedderConfig,
) {
    companion object {
        fun parse(text: String): QorganConfig = fromJson(Json.parseToJsonElement(text).jsonObject)

        fun fromJson(root: JsonObject): QorganConfig {
            val taxonomy = root.obj("taxonomy")
            return QorganConfig(
                locales = root.arr("locales").strings(),
                defaultLocale = root.str("default_locale"),
                window = WindowConfig.fromJson(root.obj("window")),
                meter = MeterConfig.fromJson(root.obj("meter")),
                scoring = ScoringConfig.fromJson(root.obj("scoring")),
                hardSignalIds = taxonomy.arr("hard_signal_ids").strings(),
                tactics = taxonomy.arr("tactics").associate { t ->
                    val o = t.asObj()
                    o.str("id") to o.obj("names").stringMap()
                },
                advice = root.obj("advice").mapValues { AdviceTexts.fromJson(it.value.asObj()) },
                templates = root.obj("templates").mapValues { Templates.fromJson(it.value.asObj()) },
                embedder = EmbedderConfig.fromJson(root.obj("embedder")),
            )
        }
    }
}

data class WindowConfig(val headUtterances: Int, val join: String, val maxChars: Int) {
    companion object {
        fun fromJson(o: JsonObject) = WindowConfig(o.int("head_utterances"), o.str("join"), o.int("max_chars"))
    }
}

data class Bands(val lowMax: Double, val mediumMax: Double, val highMax: Double, val scoreMax: Double)

data class MeterConfig(
    val alphaUp: Double,
    val alphaDown: Double,
    val bands: Bands,
    val enter: Double,
    val exit: Double,
    val hardSignalConfidenceFloor: Double,
    val singleHardSignalFloor: Double,
    val doubleHardSignalFloor: Double,
    val minTurnsToArm: Int,
    val shortWindowTurns: Int,
) {
    companion object {
        fun fromJson(o: JsonObject): MeterConfig {
            val b = o.obj("bands")
            return MeterConfig(
                alphaUp = o.num("alpha_up"),
                alphaDown = o.num("alpha_down"),
                bands = Bands(b.num("low_max"), b.num("medium_max"), b.num("high_max"), b.num("score_max")),
                enter = o.num("enter"),
                exit = o.num("exit"),
                hardSignalConfidenceFloor = o.num("hard_signal_confidence_floor"),
                singleHardSignalFloor = o.num("single_hard_signal_floor"),
                doubleHardSignalFloor = o.num("double_hard_signal_floor"),
                minTurnsToArm = o.numOr("min_turns_to_arm", 1.0).toInt(),
                shortWindowTurns = o.numOr("short_window_turns", 1.0).toInt(),
            )
        }
    }
}

data class ScoringConfig(
    val attributionTopK: Int,
    val attributionMinScore: Double,
    val calibratedBackends: List<String>,
    val confidenceHigh: Double,
    val confidenceMedium: Double,
    val lowConfidenceFloor: Double,
    val riskThreshold: Double,
) {
    companion object {
        fun fromJson(o: JsonObject): ScoringConfig {
            val bands = o.obj("confidence_bands")
            return ScoringConfig(
                attributionTopK = o.int("attribution_top_k"),
                attributionMinScore = o.num("attribution_min_score"),
                calibratedBackends = o.arr("calibrated_backends").strings(),
                confidenceHigh = bands.num("high"),
                confidenceMedium = bands.num("medium"),
                lowConfidenceFloor = o.num("low_confidence_floor"),
                riskThreshold = o.num("risk_threshold"),
            )
        }
    }
}

data class AdviceTexts(
    val tacticAdvice: Map<String, String>,
    val verificationQuestions: List<String>,
    val lowConfidenceNote: String,
) {
    companion object {
        fun fromJson(o: JsonObject) = AdviceTexts(
            tacticAdvice = o.obj("tactic_advice").stringMap(),
            verificationQuestions = o.arr("verification_questions").strings(),
            lowConfidenceNote = o.str("low_confidence_note"),
        )
    }
}

data class Templates(
    val caveat: String,
    val confidence: Map<String, String>,
    val humanNote: String,
    val noSignalReason: String,
    val reasonTemplate: String,
    val spansPlaceholder: String,
    val uncalibratedSuffix: String,
) {
    companion object {
        fun fromJson(o: JsonObject) = Templates(
            caveat = o.str("caveat"),
            confidence = o.obj("confidence").stringMap(),
            humanNote = o.str("human_note"),
            noSignalReason = o.str("no_signal_reason"),
            reasonTemplate = o.str("reason_template"),
            spansPlaceholder = o.str("spans_placeholder"),
            uncalibratedSuffix = o.str("uncalibrated_suffix"),
        )
    }
}

data class EmbedderConfig(val modelId: String, val dtype: String, val prefix: String) {
    companion object {
        fun fromJson(o: JsonObject) = EmbedderConfig(o.str("model_id"), o.str("dtype"), o.str("prefix"))
    }
}
